// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { exactMatchQuery } from "../../../main/frontend/graph-explorer/facet-queries.ts";
import {
  predicateCensusQuery,
  predicateProbeQuery,
  predicateValuesQuery,
  statementsQuery,
} from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";

const ONE = "http://example.org/one";
const TWO = "http://example.org/two";
const AGE = "http://example.org/age";

/** The subqueries of a per-node UNION: each `{ SELECT … } LIMIT n }` block. */
const subqueries = (query) => query.match(/\{\s*SELECT DISTINCT[^]*?\}\s*LIMIT \d+/g) ?? [];

test("each node's statements come from its own capped, distinct subquery without triple terms", () => {
  const query = statementsQuery([ONE, TWO], "default");
  const parts = subqueries(query);
  assert.equal(parts.length, 2);
  for (const [index, id] of [ONE, TWO].entries()) {
    assert.match(parts[index], new RegExp(`VALUES \\?s \\{ <${id}> \\}`));
    assert.match(parts[index], /LIMIT 101$/);
    assert.match(parts[index], /FILTER\(!isTRIPLE\(\?o\)\)/);
  }
  assert.match(query, /^SELECT \?s \?p \?o WHERE/);
  assert.equal(subqueries(statementsQuery([ONE], "default", 7))[0].endsWith("LIMIT 7"), true);
});

test("the node's VALUES sits inside every scoped pattern, so a graph scope never scans unbound", () => {
  const all = statementsQuery([ONE], "all");
  // Both branches of the all-graphs union restrict ?s themselves.
  assert.equal(all.match(/VALUES \?s \{ <http:\/\/example\.org\/one> \}/g)?.length, 2);
  assert.match(all, /GRAPH \?__graph \{ VALUES \?s \{ <http:\/\/example\.org\/one> \} \?s \?p \?o \./);
  const named = statementsQuery([ONE], "http://example.org/graph");
  assert.match(named, /GRAPH <http:\/\/example\.org\/graph> \{ VALUES \?s \{ <http:\/\/example\.org\/one> \}/);
});

test("fixed blank references are queried; values, scoped blank nodes and unsafe IRIs are refused", () => {
  assert.match(statementsQuery(["<_:b1>"], "default"), /VALUES \?s \{ <_:b1> \}/);
  assert.throws(() => statementsQuery(['__rdf_literal__:{"type":"literal","value":"x"}'], "default"));
  assert.throws(() => statementsQuery(["__rdf_bnode__:b1"], "default"));
  assert.throws(() => statementsQuery(["http://example.org/x> } INSERT DATA { <a> <b> <c>"], "default"));
  assert.throws(() => statementsQuery([ONE], "default", 0));
  assert.throws(() => statementsQuery([ONE], "default", 10_001));
});

test("a census counts a node's predicates over a capped set of distinct statements", () => {
  const query = predicateCensusQuery(ONE, "all", 10_001);
  assert.match(query, /^SELECT \?p \(COUNT\(\?o\) AS \?n\) WHERE/);
  assert.match(query, /SELECT DISTINCT \?p \?o WHERE/);
  assert.match(query, /LIMIT 10001/);
  assert.match(query, /GROUP BY \?p$/);
  assert.equal(query.match(/VALUES \?s \{ <http:\/\/example\.org\/one> \}/g)?.length, 2);
});

test("probes ask once per candidate predicate whether the node has it", () => {
  const query = predicateProbeQuery(ONE, [AGE, "http://example.org/born"], "default");
  assert.equal((query.match(/LIMIT 1\b/g) ?? []).length, 2);
  assert.match(query, /SELECT \(<http:\/\/example\.org\/age> AS \?p\)/);
  assert.match(query, /\?s <http:\/\/example\.org\/born> \?o/);
  assert.throws(() => predicateProbeQuery(ONE, ["not an iri"], "default"));
});

test("values come per predicate, distinct and capped one past the display cap", () => {
  const query = predicateValuesQuery(ONE, [AGE], "default");
  assert.match(query, /SELECT DISTINCT \(<http:\/\/example\.org\/age> AS \?p\) \?o WHERE/);
  assert.match(query, /LIMIT 1001/);
  assert.match(query, /FILTER\(!isTRIPLE\(\?o\)\)/);
  assert.match(predicateValuesQuery(ONE, [AGE], "default", 11), /LIMIT 11/);
});

test("exact matches check selected values, a blank value or a range for the given nodes", () => {
  const literal = '__rdf_literal__:{"type":"literal","value":"39","datatype":"http://www.w3.org/2001/XMLSchema#integer","language":""}';
  const values = exactMatchQuery([ONE, TWO], AGE, { values: [literal, TWO] }, "default");
  assert.match(values, /^SELECT DISTINCT \?s WHERE/);
  assert.match(values, /VALUES \?s \{ <http:\/\/example\.org\/one> <http:\/\/example\.org\/two> \}/);
  assert.match(values, /\?s <http:\/\/example\.org\/age> \?o \./);
  assert.match(values, /VALUES \?o \{ "39"\^\^<http:\/\/www\.w3\.org\/2001\/XMLSchema#integer> <http:\/\/example\.org\/two> \}/);

  const blank = exactMatchQuery([ONE], AGE, { values: ["__rdf_blank_value__"] }, "default");
  assert.match(blank, /FILTER\(isBlank\(\?o\)\)/);
  assert.match(exactMatchQuery([ONE], AGE, { values: ["__rdf_blank_value__", TWO] }, "default"),
    /FILTER\(isBlank\(\?o\) \|\| sameTerm\(\?o, <http:\/\/example\.org\/two>\)\)/);

  const range = exactMatchQuery([ONE], AGE, { range: { kind: "number", from: "30", to: "40" } }, "all");
  assert.match(range, /FILTER\(isLiteral\(\?o\)/);
  assert.equal(range.match(/VALUES \?s/g)?.length, 2, "the range check is scoped like the others");

  assert.match(exactMatchQuery([ONE], AGE, { values: [] }, "default"), /FILTER\(false\)/);
});
